/**
 * HTMX Declarative Enhancer Local Offline (app/static/vendor/htmx.min.js)
 * Suporta hx-get, hx-post, hx-put, hx-delete, hx-target, hx-swap e hx-confirm
 * 100% offline sem dependência de CDN externa, com fallback progressivo para forms HTML.
 */
(function () {
  "use strict";

  async function handleHxRequest(el, method, url, formData) {
    const confirmMsg = el.getAttribute("hx-confirm");
    if (confirmMsg && !window.confirm(confirmMsg)) {
      return;
    }
    const targetSelector = el.getAttribute("hx-target");
    const swapMode = el.getAttribute("hx-swap") || "innerHTML";
    const targetEl = targetSelector ? document.querySelector(targetSelector) : el;

    try {
      el.classList.add("hx-request-active");
      const opts = {
        method: method.toUpperCase(),
        headers: { "HX-Request": "true" },
      };
      if (formData && method.toUpperCase() !== "GET") {
        opts.body = formData;
      } else if (formData && method.toUpperCase() === "GET") {
        const params = new URLSearchParams(formData).toString();
        url = url + (url.includes("?") ? "&" : "?") + params;
      }
      const resp = await fetch(url, opts);
      if (resp.redirected) {
        window.location.href = resp.url;
        return;
      }
      const html = await resp.text();
      if (targetEl) {
        if (swapMode === "outerHTML") {
          targetEl.outerHTML = html;
        } else if (swapMode === "beforeend") {
          targetEl.insertAdjacentHTML("beforeend", html);
        } else if (swapMode === "afterbegin") {
          targetEl.insertAdjacentHTML("afterbegin", html);
        } else {
          targetEl.innerHTML = html;
        }
        bindHxElements(document);
      }
    } catch (err) {
      console.error("Erro na requisição HTMX local:", err);
    } finally {
      el.classList.remove("hx-request-active");
    }
  }

  function bindHxElements(root) {
    const elements = root.querySelectorAll(
      "[hx-get], [hx-post], [hx-put], [hx-delete]"
    );
    elements.forEach(function (el) {
      if (el.dataset.hxBound === "true") return;
      el.dataset.hxBound = "true";

      const method = el.hasAttribute("hx-post")
        ? "POST"
        : el.hasAttribute("hx-put")
        ? "PUT"
        : el.hasAttribute("hx-delete")
        ? "DELETE"
        : "GET";
      const url =
        el.getAttribute("hx-post") ||
        el.getAttribute("hx-put") ||
        el.getAttribute("hx-delete") ||
        el.getAttribute("hx-get");

      if (el.tagName === "FORM") {
        el.addEventListener("submit", function (e) {
          e.preventDefault();
          const fd = new FormData(el);
          handleHxRequest(el, method, url, fd);
        });
      } else {
        el.addEventListener("click", function (e) {
          e.preventDefault();
          handleHxRequest(el, method, url, null);
        });
      }
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    bindHxElements(document);
  });
})();
